-- ---------------------------------------------------------------------------
-- Guard rails Prisma cannot express.
-- ---------------------------------------------------------------------------

-- A zone area maps exactly one district OR one upazila.
ALTER TABLE "ShippingZoneArea" ADD CONSTRAINT "ShippingZoneArea_one_target"
  CHECK (("districtId" IS NULL) <> ("upazilaId" IS NULL));

-- A coupon scope names exactly one category OR one product.
ALTER TABLE "CouponScope" ADD CONSTRAINT "CouponScope_one_target"
  CHECK (("categoryId" IS NULL) <> ("productId" IS NULL));

-- A line's share of the discount is never negative or more than the line.
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_discount_valid"
  CHECK ("discountPoisha" >= 0 AND "discountPoisha" <= "lineTotalPoisha");

-- Blocked numbers are stored normalised (+8801XXXXXXXXX).
ALTER TABLE "BlockedPhone" ADD CONSTRAINT "BlockedPhone_phone_format"
  CHECK ("phone" ~ '^\+8801[3-9][0-9]{8}$');

-- ---------------------------------------------------------------------------
-- Approved change: FREE_SHIPPING coupons carry value 0.
-- ---------------------------------------------------------------------------
ALTER TABLE "Coupon" DROP CONSTRAINT "Coupon_value_valid";
ALTER TABLE "Coupon" ADD CONSTRAINT "Coupon_value_valid" CHECK (
  ("type" = 'PERCENTAGE' AND "value" BETWEEN 1 AND 100)
  OR ("type" = 'FIXED' AND "value" > 0)
  OR ("type" = 'FREE_SHIPPING' AND "value" = 0)
);
